Q: How to check, and add, a user to a user database map? A: <p><a href="https://en.cppreference.com/w/cpp/container/map.html" rel="nofollow noreferrer"><code>std::map</code></a> has a <a href="https://en.cppreference.com/w/cpp/container/map/find.html" rel="nofollow noreferrer"><code>find()</code></a> method to search for an existing key, eg:</p>
<pre class="lang-cpp prettyprint-override"><code>auto iter = userdatabase.find(username);
if (iter != userdatabase.end()) {
    // username found
    // use *iter if needed to access their Userlogin
}
else {
    // username not found
}
</code></pre>
<p>For example:</p>
<pre class="lang-cpp prettyprint-override"><code>#include &lt;iostream&gt;
#include &lt;map&gt;
#include &lt;string&gt;

struct Userlogin
{
    std::string password;
    double balance;
};

int main(){

    std::string user_name, password, new_user;
    std::map&lt;std::string, Userlogin&gt; user_db;

    std::cout &lt;&lt; &quot;Welcome to the 777 machine\n&quot;;

    std::cout &lt;&lt; &quot;Did you want to create a new account?: &quot;;
    std::cin &gt;&gt; new_user;

    if (new_user = &quot;Yes&quot; || new_user = &quot;y&quot; || new_user = &quot;Y&quot;) {
        do {
            std::cout &lt;&lt; &quot;Please enter your new username: &quot;;
            std::cin &gt;&gt; user_name;
            if (user_db.find(user_name) == user_db.end())
                break;
            }
            std::cout &lt;&lt; &quot;\nThat username is already taken.\n&quot;;
        }
        while (true);

        std::cout &lt;&lt; &quot;\nPlease enter your new password: &quot;
        std::cin &gt;&gt; password;

        Userlogin login;
        login.password = password;
        login.balance = 0.0;

        user_db[user_name] = login;
    }

    return 0;
}
</code></pre>

Q: How to compute the sum of multiple columns in PostgreSQL A: <p>You can just add multiple sum functions with the &quot;+&quot; operator:</p>
<pre class="lang-sql prettyprint-override"><code>SELECT SUM(col1) + SUM(col2) FROM table1;
</code></pre>

